card(14,2, sub="Day 2: Score it yourself",
 focus="Today you score your own story against a rubric — the same kind a teacher uses — so you know what’s strong and what still needs work. Then you pick ONE row to make better before you publish. Not everything. One.",
 anne="Chapter 36: the Avery scholarship. Anne is judged, and she takes the judging well. Scoring your own work honestly is a skill, and it’s harder than it sounds.",
 watch=dict(intro="Sam scores his story 1–3 in five rows, then picks one to fix.",
   page=["<b>Ideas</b> 3 ✓ · <b>Organization</b> 3 ✓ · <b>Word Choice</b> 2 (a few plain words in Scene 2) · <b>Voice</b> 3 ✓ · <b>Conventions</b> 2 (one comma he’s not sure about)","Sam picks <b>Word Choice</b>. He goes back to Scene 2 and changes “kicking balls around” to “juggling balls off their knees.” One fix."],
   notice="Sam didn’t try to fix everything. He picked one row that scored a 2 and made it a 3. That’s a real publish-week move: one targeted fix."),
 tool=dict(title="Realistic Fiction Rubric (self-score)", intro="Score yourself 1, 2 or 3 in each row. Be honest.",
   table=[["Row","3 (strong)","2 (ok)","1 (weak)"],["Ideas","a real kid, a real problem, interesting","somewhat","vague"],["Organization","five scenes, clear order, strong start and end","middle could be stronger","confusing order"],["Word Choice","specific, vivid","some plain words still","very plain"],["Voice","sounds like a real person","some feeling","flat"],["Conventions","capitals, punctuation, spelling right","a few slips","many slips"]],
   yourturn="Ideas __ · Organization __ · Word Choice __ · Voice __ · Conventions __ → the ONE row I’ll fix: ____"),
 frames=["My strongest row is ___ because ___.","The row I want to improve is ___.","I will fix ___ by changing ___.","After the fix, ___ is a 3."],
 ms="Today: make your one targeted fix in the draft.",
 prompt="Score your story 1–3 in all five rows. Then pick ONE row to improve and name TWO specific things you changed in your draft to do it.",
 ph="Ideas: __ Organization: __ Word Choice: __ Voice: __ Conventions: __ / I improved ___ by: 1) ___ 2) ___")

